// NODE 3 - TRIAGE
// Decide whether this PDF has a usable text layer or needs OCR.
// A scanned page yields almost no characters; a digital one yields hundreds.

const item = $input.first().json;
const text = item.text || '';
const pages = item.numpages || 1;
const charsPerPage = text.replace(/\s/g, '').length / pages;

// 80 chars/page is the empirical floor. Below it, the text layer is either
// absent or is junk from a bad scan, and OCR beats parsing garbage.
const SCANNED_THRESHOLD = 80;
const isScanned = charsPerPage < SCANNED_THRESHOLD;

return [{
  json: {
    text,
    pages,
    charsPerPage: Math.round(charsPerPage),
    route: isScanned ? 'scanned' : 'digital',
    openingBalanceHint: $('Upload PDF').first().json['Opening balance (optional)'] ?? null
  },
  binary: $input.first().binary
}];

// NODE 5 - LAYOUT NORMALISATION  *** THE MOAT ***
//
// Raw PDF text is not rows. It is a stream of lines in which one transaction
// may span three lines, a page header repeats every page, and a row can be
// split across a page break. Feeding that straight to an LLM is why the cheap
// templates hallucinate. This node rebuilds real rows deterministically.

const src = $json.text || $json.pages?.map(p => p.markdown).join('\n') || '';
const rawLines = src.split(/\r?\n/).map(l => l.replace(/ /g, ' ').trimEnd());

// --- 1. Kill repeated headers and footers -------------------------------
// Any line appearing on most pages at low variance is furniture, not data.
const freq = {};
for (const l of rawLines) {
  const k = l.trim();
  if (k.length > 3) freq[k] = (freq[k] || 0) + 1;
}
const pageCount = Math.max(1, $json.pages?.length || $json.pages || 1);
const furniture = new Set(
  Object.entries(freq)
    .filter(([k, n]) => n >= Math.max(2, pageCount * 0.6) && !/\d{2}[\/\-.]\d{2}/.test(k))
    .map(([k]) => k)
);

// Page-number lines: "Page 3 of 11", bare numerals.
const isPageNo = l => /^\s*(page\s*)?\d+\s*(of\s*\d+)?\s*$/i.test(l);

const lines = rawLines.filter(l =>
  l.trim() && !furniture.has(l.trim()) && !isPageNo(l)
);

// --- 2. Amount parsing ---------------------------------------------------
// Handles 1,234.56 / (1,234.56) accounting negatives / trailing CR-DR markers.
const AMOUNT_RE = /\(?-?(?:\d{1,3}(?:,\d{2,3})+|\d+)\.\d{2}\)?(?:\s*(?:CR|DR))?/gi;

function parseAmount(tok) {
  const neg = /^\(.*\)$/.test(tok.trim()) || /DR\s*$/i.test(tok);
  const n = parseFloat(tok.replace(/[(),\s]|CR|DR/gi, ''));
  if (Number.isNaN(n)) return null;
  return neg ? -Math.abs(n) : n;
}

function amountsIn(line) {
  return (line.match(AMOUNT_RE) || []).map(parseAmount).filter(v => v !== null);
}

// --- 3. Boundary markers -------------------------------------------------
// A new transaction starts with a date. Everything until the next date is a
// continuation - that is how wrapped descriptions and page-break splits get
// stitched back together.
const DATE_RE = /^\s*(\d{1,2}[\/\-.](?:\d{1,2}|[A-Za-z]{3})[\/\-.]\d{2,4}|\d{4}-\d{2}-\d{2})/;

// TERMINATOR: a summary line is NOT a continuation of the last transaction.
// Without this the closing-balance figure is swallowed into the final row's
// amount list, and on statements where that line carries its own total the
// last row's balance silently becomes the wrong number.
// NOTE: \w* after "bal", not \b - a word boundary cannot match between
// "bal" and "ance", so \b here silently never fires on "CLOSING BALANCE".
const TERMINATOR_RE = /^\s*(closing\s+bal\w*|balance\s+(c\/f|carried\s+f\w*)|total\b|grand\s+total\b|net\s+(movement|total)\b|summary\b)/i;
const OPENING_RE = /^\s*(opening\s+bal\w*|balance\s+(b\/f|brought\s+f\w*))/i;

// --- 4. Row assembly -----------------------------------------------------
const rows = [];
let current = null;
let printedOpening = null;
let printedClosing = null;

for (const line of lines) {
  const bare = line.trim();

  if (OPENING_RE.test(bare) && !DATE_RE.test(bare)) {
    const a = amountsIn(bare);
    if (a.length) printedOpening = a[a.length - 1];
    continue;                       // never a transaction, never a continuation
  }

  if (TERMINATOR_RE.test(bare) && !DATE_RE.test(bare)) {
    const a = amountsIn(bare);
    if (a.length) printedClosing = a[a.length - 1];
    if (current) { rows.push(current); current = null; }
    continue;                       // closes the open row and swallows nothing
  }

  if (DATE_RE.test(line)) {
    if (current) rows.push(current);
    current = { raw: line, continuations: [] };
  } else if (current) {
    current.continuations.push(bare);
  }
  // Lines before the first date are preamble (account no, address) - dropped.
}
if (current) rows.push(current);

// --- 5. Date format inference -------------------------------------------
// "02/06/2026" is 2 June or 6 February depending on the issuer, and JS's
// Date() silently assumes MM/DD. That is real corruption, not a crash: days
// <= 12 parse to the WRONG date without erroring, days > 12 throw. So infer
// the order ONCE from the whole statement, then parse explicitly. The LLM is
// never asked to guess a date - it receives an ISO string already resolved.
const MONTHS = { jan:1, feb:2, mar:3, apr:4, may:5, jun:6,
                 jul:7, aug:8, sep:9, oct:10, nov:11, dec:12 };

const flats = rows.map(r =>
  [r.raw, ...r.continuations].join(' ').replace(/\s{2,}/g, ' ').trim());
const dateStrs = flats.map(f => (f.match(DATE_RE) || [''])[0].trim());

let dayFirst = 0, monthFirst = 0;
for (const s of dateStrs) {
  const m = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.]\d{2,4}$/);
  if (!m) continue;
  if (+m[1] > 12) dayFirst++;    // first component cannot be a month
  if (+m[2] > 12) monthFirst++;  // second component cannot be a month
}

let dateOrder = 'DMY';
let dateOrderConfident = false;
if (dayFirst && !monthFirst)      { dateOrder = 'DMY'; dateOrderConfident = true; }
else if (monthFirst && !dayFirst) { dateOrder = 'MDY'; dateOrderConfident = true; }
else if (dayFirst && monthFirst)  { dateOrder = 'CONFLICT'; }
// else every day is <= 12: genuinely undecidable from the document alone.
// DMY is assumed and dateOrderConfident stays false, so the caller can see it.

function toIso(s) {
  if (!s) return null;
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) return s;

  m = s.match(/^(\d{1,2})[\/\-.]([A-Za-z]{3})[\/\-.](\d{2,4})$/);
  if (m) {
    const mo = MONTHS[m[2].toLowerCase()];
    if (!mo) return null;
    const y = m[3].length === 2 ? '20' + m[3] : m[3];
    return `${y}-${String(mo).padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  }

  m = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})$/);
  if (m) {
    if (dateOrder === 'CONFLICT') return null;
    const d  = dateOrder === 'MDY' ? m[2] : m[1];
    const mo = dateOrder === 'MDY' ? m[1] : m[2];
    const y  = m[3].length === 2 ? '20' + m[3] : m[3];
    if (+mo < 1 || +mo > 12 || +d < 1 || +d > 31) return null;
    return `${y}-${mo.padStart(2, '0')}-${d.padStart(2, '0')}`;
  }
  return null;
}

// --- 6. Field extraction (deterministic - the LLM never sees a bare number)
const statement = {
  printedOpening, printedClosing, rowCount: rows.length,
  dateOrder, dateOrderConfident
};

const candidates = rows.map((r, i) => {
  const flat = flats[i];
  const tokens = flat.match(AMOUNT_RE) || [];
  const amounts = tokens.map(parseAmount).filter(v => v !== null);
  const dateStr = dateStrs[i];
  const dateIso = toIso(dateStr);

  // Description = the row with dates and money stripped out.
  // split/join, not replace(str): replace() removes only the FIRST occurrence,
  // so a repeated amount (amount == balance, or a ref equal to a figure) left a
  // stray number in the description.
  let description = flat.replace(DATE_RE, '');
  for (const t of tokens) description = description.split(t).join(' ');
  description = description.replace(/\s{2,}/g, ' ').trim();

  // The debit/credit/balance live in the RIGHTMOST columns, so the trailing
  // amounts are the real money; a figure embedded mid-description comes before
  // them. Handing the LLM these as the candidates keeps phantom amounts inside
  // descriptions from being mistaken for a transaction value.
  const columnAmounts = amounts.slice(-3);

  return {
    rowIndex: i,
    dateStr,
    dateIso,              // resolved here, never guessed downstream
    description,
    amounts,              // full row, left-to-right as printed (context)
    columnAmounts,        // rightmost <=3 - the actual money columns
    amountCount: amounts.length,
    wrapped: r.continuations.length > 0,
    raw: flat,
    _statement: statement
  };
});

// Convention check: on most statements the LAST amount on a row is the running
// balance. Verified downstream in node 7 - never assumed to be true here.
return candidates.map(c => ({ json: c }));

