// NODE 7 - VALIDATION & RECONCILIATION  *** THE PROOF ***
//
// This is the claim you can make that nobody else in this market can:
// every row is checked against the statement's own arithmetic, or flagged.
// Confidence is scored PER FIELD, not per row - a clean date beside an
// ambiguous amount should flag the amount only.

const items = $input.all().map(i => i.json);
const TOL = 0.01; // one paisa/cent of float tolerance

// Opening balance: prefer what the STATEMENT printed over what the user typed.
// The terminator rule in node 5 captures both printed anchors; the form field
// is only a fallback for statements that print neither.
const stmt = items.length ? (items[0]._statement || {}) : {};
const hint = $('Triage: digital or scanned').first().json.openingBalanceHint;
const openingBalance = stmt.printedOpening ?? hint ?? null;

// #1 Does this statement even have a running-balance column? Cards and most
// invoices do not, and flagging every row balance_missing made a perfectly good
// extraction read as "0% reconciled". Detect it once, up front.
const withBalance = items.filter(
  r => r.balance !== null && r.balance !== undefined && r.balance !== '').length;
const hasBalanceColumn = items.length > 0 && withBalance >= items.length * 0.5;

const out = [];
let prevBalance = openingBalance;
let movements = 0;
let prevDate = null;

for (let i = 0; i < items.length; i++) {
  const r = items[i];
  const flags = [];
  const confidence = { date: 1, description: 1, debit: 1, credit: 1, balance: 1 };

  // --- date ---------------------------------------------------------------
  // Strict ISO only. Never hand an ambiguous dd/mm string to Date() - it
  // assumes MM/DD and corrupts every day <= 12 without raising anything.
  // Node 5 has already resolved the statement's date order.
  const iso = typeof r.date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(r.date)
    ? r.date : null;
  const d = iso ? new Date(iso + 'T00:00:00Z') : null;
  if (!d || Number.isNaN(d.getTime())) {
    flags.push('date_unparseable');
    confidence.date = 0;
  } else {
    // Statements run forward. A backwards step usually means two rows merged.
    if (prevDate && d < prevDate) {
      flags.push('date_out_of_order');
      confidence.date = 0.4;
    }
    prevDate = d;
  }

  // --- movement -----------------------------------------------------------
  const debit = Number(r.debit) || 0;
  const credit = Number(r.credit) || 0;
  if (debit && credit) {
    flags.push('both_debit_and_credit');
    confidence.debit = confidence.credit = 0.3;
  }
  if (!debit && !credit) {
    flags.push('no_movement');
    confidence.debit = confidence.credit = 0.2;
  }
  const movement = credit - debit;

  // --- running balance: the load-bearing check ----------------------------
  const bal = r.balance === null || r.balance === undefined ? null : Number(r.balance);
  if (!hasBalanceColumn) {
    // No balance column in this statement - nothing to reconcile against.
    // Not an error: the row is extracted, just not reconcilable.
    confidence.balance = null;
  } else if (bal === null) {
    flags.push('balance_missing');
    confidence.balance = 0;
  } else if (prevBalance !== null && prevBalance !== undefined) {
    const expected = prevBalance + movement;
    const drift = Math.abs(expected - bal);
    if (drift > TOL) {
      flags.push(`balance_mismatch:expected_${expected.toFixed(2)}_got_${bal.toFixed(2)}`);
      confidence.balance = 0;
      // A mismatch usually means the MOVEMENT was misread, not the balance -
      // the balance is printed, the split into debit/credit is inferred.
      confidence.debit = Math.min(confidence.debit, 0.2);
      confidence.credit = Math.min(confidence.credit, 0.2);
    }
  }

  if (bal !== null) prevBalance = bal;
  movements += movement;

  const rowConfidence = Math.min(
    ...Object.values(confidence).filter(v => v !== null));

  out.push({
    json: {
      ...r,
      rowIndex: i,
      movement: Number(movement.toFixed(2)),
      flags,
      confidence,
      rowConfidence,
      reconciled: flags.length === 0
    }
  });
}

// --- statement-level close-out ---------------------------------------------
const opening = openingBalance;
const closing = out.length ? out[out.length - 1].json.balance : null;

let statementReconciles = null;
if (hasBalanceColumn && opening !== null && closing !== null) {
  statementReconciles = Math.abs((opening + movements) - closing) <= TOL;
}

// Independent second check: the statement's OWN printed closing figure. This
// catches a whole class of errors the running-balance walk cannot see - if a
// transaction row was missed entirely, every remaining row still chains
// correctly and only this comparison notices the gap.
let printedClosingMatches = null;
if (hasBalanceColumn && stmt.printedClosing !== null && stmt.printedClosing !== undefined && closing !== null) {
  printedClosingMatches = Math.abs(stmt.printedClosing - closing) <= TOL;
}

const flagged = out.filter(o => !o.json.reconciled).length;
for (const o of out) {
  o.json._summary = {
    rows: out.length,
    flagged,
    hasBalanceColumn,
    reconciliation: hasBalanceColumn ? 'checked'
      : 'not_applicable_no_balance_column',
    reconciledPct: !hasBalanceColumn ? null
      : (out.length ? Number(((out.length - flagged) / out.length * 100).toFixed(1)) : 0),
    statementReconciles,
    printedClosingMatches,
    dateOrder: stmt.dateOrder ?? null,
    dateOrderConfident: stmt.dateOrderConfident ?? null,
    printedOpening: stmt.printedOpening ?? null,
    printedClosing: stmt.printedClosing ?? null,
    sumOfMovements: Number(movements.toFixed(2)),
    closingBalance: closing
  };
}

return out;
